/* Library-level differential driver for libogg bitwise.c (oggpack_* / oggpackB_*).
 *
 * The SAME driver source is linked against (a) the original libogg C (bitwise.c, upstream
 * 0288fad, shipped in sactor-datasets/ogg/ogg) and (b) a SACTOR Rust translation of bitwise.c
 * (built as a cdylib exporting the C ABI, exactly as SACTOR's own E2E check links it). Only the
 * library differs between the two binaries.
 *
 * Input: a call-sequence script on stdin, one op per line (generated by gen_cases.py).
 * Output: one line per op on stdout with every value the public API returns
 * (return values, oggpack_bytes/bits, the written buffer via get_buffer).
 * Nothing reads struct fields directly; only the public API is observed.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ogg/ogg.h>

typedef struct {
  void (*writeinit)(oggpack_buffer *);
  int (*writecheck)(oggpack_buffer *);
  void (*writetrunc)(oggpack_buffer *, long);
  void (*write)(oggpack_buffer *, unsigned long, int);
  void (*writealign)(oggpack_buffer *);
  void (*writecopy)(oggpack_buffer *, void *, long);
  void (*reset)(oggpack_buffer *);
  void (*writeclear)(oggpack_buffer *);
  void (*readinit)(oggpack_buffer *, unsigned char *, int);
  long (*look)(oggpack_buffer *, int);
  long (*look1)(oggpack_buffer *);
  void (*adv)(oggpack_buffer *, int);
  void (*adv1)(oggpack_buffer *);
  long (*read)(oggpack_buffer *, int);
  long (*read1)(oggpack_buffer *);
  long (*bytes)(oggpack_buffer *);
  long (*bits)(oggpack_buffer *);
  unsigned char *(*get_buffer)(oggpack_buffer *);
} fam_t;

static const fam_t FAM_L = {oggpack_writeinit, oggpack_writecheck, oggpack_writetrunc, oggpack_write,
  oggpack_writealign, oggpack_writecopy, oggpack_reset, oggpack_writeclear, oggpack_readinit,
  oggpack_look, oggpack_look1, oggpack_adv, oggpack_adv1, oggpack_read, oggpack_read1,
  oggpack_bytes, oggpack_bits, oggpack_get_buffer};
static const fam_t FAM_B = {oggpackB_writeinit, oggpackB_writecheck, oggpackB_writetrunc, oggpackB_write,
  oggpackB_writealign, oggpackB_writecopy, oggpackB_reset, oggpackB_writeclear, oggpackB_readinit,
  oggpackB_look, oggpackB_look1, oggpackB_adv, oggpackB_adv1, oggpackB_read, oggpackB_read1,
  oggpackB_bytes, oggpackB_bits, oggpackB_get_buffer};

static unsigned long long lcg_state;
static unsigned char lcg_byte(void) {
  lcg_state = lcg_state * 6364136223846793005ULL + 1442695040888963407ULL;
  return (unsigned char)(lcg_state >> 33);
}

static void hexline(const char *tag, const unsigned char *p, long n) {
  printf("%s n=%ld", tag, n);
  if (!p) { printf(" NULL\n"); return; }
  printf(" ");
  for (long i = 0; i < n; i++) printf("%02x", p[i]);
  printf("\n");
}

int main(void) {
  const fam_t *F = &FAM_L;
  oggpack_buffer W, R;
  memset(&W, 0, sizeof W);
  memset(&R, 0, sizeof R);
  unsigned char *rbuf = NULL;   /* backing store of the reader; owned by the driver */
  char line[65536];
  char op[32];
  long ln = 0;
  setvbuf(stdout, NULL, _IOLBF, 0);
  while (fgets(line, sizeof line, stdin)) {
    ln++;
    if (sscanf(line, "%31s", op) != 1) continue;
    char *args = line + strlen(op);
    if (!strcmp(op, "mode")) {
      char m[4];
      sscanf(args, "%3s", m);
      F = (m[0] == 'B') ? &FAM_B : &FAM_L;
      printf("%ld mode %c\n", ln, m[0] == 'B' ? 'B' : 'L');
    } else if (!strcmp(op, "winit")) {
      F->writeinit(&W);
      printf("%ld winit\n", ln);
    } else if (!strcmp(op, "wcheck")) {
      printf("%ld wcheck %d\n", ln, F->writecheck(&W));
    } else if (!strcmp(op, "w")) {
      unsigned long v; int n;
      sscanf(args, "%lu %d", &v, &n);
      F->write(&W, v, n);
      printf("%ld w bytes=%ld bits=%ld\n", ln, F->bytes(&W), F->bits(&W));
    } else if (!strcmp(op, "walign")) {
      F->writealign(&W);
      printf("%ld walign bytes=%ld bits=%ld\n", ln, F->bytes(&W), F->bits(&W));
    } else if (!strcmp(op, "wtrunc")) {
      long b;
      sscanf(args, "%ld", &b);
      F->writetrunc(&W, b);
      printf("%ld wtrunc bytes=%ld bits=%ld\n", ln, F->bytes(&W), F->bits(&W));
    } else if (!strcmp(op, "wcopy")) {
      unsigned long long seed; long nbits;
      sscanf(args, "%llu %ld", &seed, &nbits);
      long nb = (nbits + 7) / 8;
      unsigned char *src = malloc(nb + 1);
      lcg_state = seed;
      for (long i = 0; i < nb + 1; i++) src[i] = lcg_byte();
      F->writecopy(&W, src, nbits);
      free(src);
      printf("%ld wcopy bytes=%ld bits=%ld\n", ln, F->bytes(&W), F->bits(&W));
    } else if (!strcmp(op, "wreset")) {
      F->reset(&W);
      printf("%ld wreset bytes=%ld bits=%ld\n", ln, F->bytes(&W), F->bits(&W));
    } else if (!strcmp(op, "wclear")) {
      F->writeclear(&W);
      printf("%ld wclear\n", ln);
    } else if (!strcmp(op, "wstate")) {
      long n = F->bytes(&W);
      unsigned char *p = F->get_buffer(&W);
      printf("%ld wstate bytes=%ld bits=%ld check=%d\n", ln, n, F->bits(&W), F->writecheck(&W));
      hexline("  wbuf", p, p ? n : 0);
    } else if (!strcmp(op, "rfromw")) {
      long n = F->bytes(&W);
      unsigned char *p = F->get_buffer(&W);
      free(rbuf);
      rbuf = malloc(n > 0 ? n : 1);
      if (p && n > 0) memcpy(rbuf, p, n);
      F->readinit(&R, rbuf, (int)(p ? n : 0));
      printf("%ld rfromw n=%ld\n", ln, p ? n : 0);
    } else if (!strcmp(op, "rhex")) {
      /* rhex DECLARED HEX : reader over the given bytes, told DECLARED bytes (<= len) */
      int declared; char hex[60000];
      hex[0] = 0;
      sscanf(args, "%d %59999s", &declared, hex);
      if (!strcmp(hex, "-")) hex[0] = 0;
      long len = (long)strlen(hex) / 2;
      free(rbuf);
      rbuf = malloc(len > 0 ? len : 1);
      for (long i = 0; i < len; i++) { unsigned int x; sscanf(hex + 2 * i, "%2x", &x); rbuf[i] = (unsigned char)x; }
      if (declared > len) declared = (int)len;
      F->readinit(&R, rbuf, declared);
      printf("%ld rhex n=%d\n", ln, declared);
    } else if (!strcmp(op, "look")) {
      int n; sscanf(args, "%d", &n);
      printf("%ld look %d = %ld\n", ln, n, F->look(&R, n));
    } else if (!strcmp(op, "look1")) {
      printf("%ld look1 = %ld\n", ln, F->look1(&R));
    } else if (!strcmp(op, "adv")) {
      int n; sscanf(args, "%d", &n);
      F->adv(&R, n);
      printf("%ld adv %d bytes=%ld bits=%ld\n", ln, n, F->bytes(&R), F->bits(&R));
    } else if (!strcmp(op, "adv1")) {
      F->adv1(&R);
      printf("%ld adv1 bytes=%ld bits=%ld\n", ln, F->bytes(&R), F->bits(&R));
    } else if (!strcmp(op, "read")) {
      int n; sscanf(args, "%d", &n);
      long v = F->read(&R, n);
      printf("%ld read %d = %ld bytes=%ld bits=%ld\n", ln, n, v, F->bytes(&R), F->bits(&R));
    } else if (!strcmp(op, "read1")) {
      long v = F->read1(&R);
      printf("%ld read1 = %ld bytes=%ld bits=%ld\n", ln, v, F->bytes(&R), F->bits(&R));
    } else if (!strcmp(op, "rstate")) {
      printf("%ld rstate bytes=%ld bits=%ld\n", ln, F->bytes(&R), F->bits(&R));
    } else {
      printf("%ld ?? %s\n", ln, op);
    }
  }
  /* W may already be cleared (writeclear memsets it); writeclear on a cleared buffer is safe in C */
  F->writeclear(&W);
  free(rbuf);
  printf("end\n");
  return 0;
}
